145		// 与身份、参数校验无关。原数据文件先挪到旁边，事后原样还原。
146		dataPath := filepath.Join(dir, dataName)
147		backupPath := dataPath + ".saved"
148		if err := os.Rename(dataPath, backupPath); err != nil {
149			t.Fatalf("backup data file: %v", err)
150		}
151		if err := os.Mkdir(dataPath, 0o755); err != nil {
152			t.Fatalf("block data path: %v", err)
153		}
154	
155		// 身份有权、患者未停用、版本号/内容/原因均合法，仅保存失败：明确报错，
156		// 且不能伪装成参数校验或版本冲突等业务结果。
157		if _, err := s.CorrectRecord(doc, r.ID, 2, "未保存的更正内容", "未保存的更正原因"); err == nil {
158			t.Fatal("correction must fail when local save fails")
159		} else if errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrConflict) ||
160			errors.Is(err, ErrAccessDenied) || errors.Is(err, ErrDeactivated) {
161			t.Fatalf("save failure surfaced as a business error: %v", err)
162		}
163		// 失败不能留下半截写入的临时文件。
164		if _, statErr := os.Stat(dataPath + ".tmp"); !os.IsNotExist(statErr) {
165			t.Fatalf("failed save left a temp file: %v", statErr)
166		}
167	
168		// 失败后：档案、就诊记录、审计与接收方读取全部维持提交前状态。
169		checkIntact("after failed save", s)
170	
171		// 关闭后从原数据位置重新打开：先恢复保存条件（还原原数据文件）。
172		if err := s.Close(); err != nil {
173			t.Fatal(err)
174		}
175		if err := os.Remove(dataPath); err != nil {
176			t.Fatalf("unblock data path: %v", err)
177		}
178		if err := os.Rename(backupPath, dataPath); err != nil {
179			t.Fatalf("restore data file: %v", err)
180		}
181	
182		s2 := open()
183		t.Cleanup(func() { _ = s2.Close() })
184		// 失败前的当前版本、完整历史与审计在重开后完整存在，
185		// 失败更正没有变成正式数据。
186		checkIntact("after reopen", s2)
187	
188		// 保存条件恢复后：用失败前的当前版本号再次提交合法更正，成功生成
189		// 紧接原当前版本的新版本——失败尝试既没有推进版本号，也没有让
190		// 原本有效的当前版本号变成冲突。
191		clk.t = clk.t.Add(time.Hour)
192		v3, err := s2.CorrectRecord(doc, r.ID, 2, "重试成功的更正内容", "保存恢复后重试")
193		if err != nil {
194			t.Fatalf("retry after save recovered: %v", err)
195		}
196		if v3.Number != 3 || v3.PrevID != v2.ID || v3.Reason != "保存恢复后重试" ||
197			v3.Content != "重试成功的更正内容" || !v3.CreatedAt.Equal(clk.t) {
198			t.Fatalf("bad v3: %+v", v3)
199		}
200	
201		chart, err := s2.Chart(doc, p.ID)
202		if err != nil {
203			t.Fatal(err)
204		}
205		hist := findHistory(chart, r.ID)
206		if hist == nil || hist.CurrentVersion == nil || hist.CurrentVersion.ID != v3.ID || len(hist.Versions) != 3 {
207			t.Fatalf("history after retry: %+v", hist)
208		}
209		// 此前历史未被丢失或覆盖。
210		if !reflect.DeepEqual(hist.Versions[0], v1) || !reflect.DeepEqual(hist.Versions[1], v2) {
211			t.Fatalf("prior history mutated by retry: %+v", hist.Versions)
212		}
213	
214		// 只新增一次对应的更正审计：既有事件原样保留，事件总数 +1。
215		audit, err := s2.AuditEvents(doc, p.ID)
216		if err != nil {
217			t.Fatal(err)
218		}
219		if len(audit) != len(auditBefore)+1 || !reflect.DeepEqual(audit[:len(auditBefore)], auditBefore) {
220			t.Fatalf("audit after retry:\nbefore: %+v\nafter:  %+v", auditBefore, audit)
221		}
222		last := audit[len(audit)-1]
223		if last.Action != ActionCorrected || last.ObjectID != r.ID || last.ActorID != doc.ID {
224			t.Fatalf("unexpected new audit event: %+v", last)
225		}
226		if got := auditActions(audit)[ActionCorrected]; got != 2 {
227			t.Fatalf("corrected events = %d, want 2", got)
228		}
229	
230		// 成功更正后接收方读到新的当前版本（既有授权行为保持不变）。
231		res, err := s2.Read(rcv, p.ID, e.ID, Diagnosis)
232		if err != nil {
233			t.Fatal(err)
234		}
235		if len(res.Records) != 1 || res.Records[0].VersionID != v3.ID ||
236			res.Records[0].Version != 3 || res.Records[0].Content != v3.Content {
237			t.Fatalf("receiver read after retry: %+v", res)
238		}
239	}
