	if err != nil {
		t.Fatal(err)
	}
	hist := findHistory(chart, r.ID)
	if hist == nil || hist.CurrentVersion == nil || hist.CurrentVersion.ID != v3.ID || len(hist.Versions) != 3 {
		t.Fatalf("history after retry: %+v", hist)
	}
