package clinical

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sync"
	"time"
)

// dataName 是存放全部业务状态的快照文件名。
const dataName = "clinical-data.json"

// dataVersion 是快照格式的版本标记，便于将来迁移。
const dataVersion = 1

// snapshot 是写入磁盘的完整状态。所有业务对象集中在一个文件中，
// 采用“临时文件 + 原子改名”整体落盘：成功操作与其审计事件一同保留，
// 失败的操作在 mutate 中就已丢弃，不会写出半截状态。
type snapshot struct {
	FormatVersion  int                       `json:"format_version"`
	Patients       map[string]*Patient       `json:"patients"`
	Encounters     map[string]*Encounter     `json:"encounters"`
	Records        map[string]*Record        `json:"records"`
	Versions       map[string]*Version       `json:"versions"`
	Authorizations map[string]*Authorization `json:"authorizations"`
	Exchanges      map[string]*Exchange      `json:"exchanges"`
	AuditEvents    []*AuditEvent             `json:"audit_events"`
}

// Clock 决定“发生时间”的来源。生产使用实时时钟；测试可注入固定/可控时钟
// 以验证开始、到期、撤回等时间边界。
type Clock func() time.Time

// Store 是本地临床档案的句柄。数据存放位置由调用方在 Open 时指定。
// 同一目录同一时刻只允许一个 Store 打开（通过锁文件互斥）。
type Store struct {
	dir   string
	clock Clock
	mu    sync.Mutex
	lock  *os.File
	data  *snapshot
}

// Option 配置 Open 的行为。
type Option func(*Store)

// WithClock 注入自定义时钟。
func WithClock(c Clock) Option {
	return func(s *Store) { s.clock = c }
}

// Open 在指定目录打开（必要时创建）本地存储。
// 调用方指定数据存放位置；关闭后从同一位置重新打开可看到全部历史，
// 到期与否始终按“本次读取时间”重新计算。
func Open(dir string, opts ...Option) (*Store, error) {
	if dir == "" {
		return nil, fmt.Errorf("%w: empty data directory", ErrInvalidArgument)
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, err
	}

	lockPath := filepath.Join(dir, ".clinical.lock")
	lockFile, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
	if err != nil {
		return nil, err
	}
	if err := tryLockFile(lockFile); err != nil {
		lockFile.Close()
		return nil, err
	}

	s := &Store{dir: dir, clock: time.Now, lock: lockFile}
	for _, opt := range opts {
		opt(s)
	}
	if s.clock == nil {
		s.clock = time.Now
	}

	if err := s.loadLocked(); err != nil {
		unlockFile(lockFile)
		lockFile.Close()
		return nil, err
	}
	return s, nil
}

func (s *Store) loadLocked() error {
	path := filepath.Join(s.dir, dataName)
	raw, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		s.data = newSnapshot()
		return nil
	}
	if err != nil {
		return err
	}
	var snap snapshot
	if err := json.Unmarshal(raw, &snap); err != nil {
		return err
	}
	if snap.FormatVersion != dataVersion {
		return fmt.Errorf("clinical: unsupported data format version %d", snap.FormatVersion)
	}
	ensureMaps(&snap)
	s.data = &snap
	return nil
}

func newSnapshot() *snapshot {
	snap := &snapshot{FormatVersion: dataVersion}
	ensureMaps(snap)
	return snap
}

func ensureMaps(snap *snapshot) {
	if snap.Patients == nil {
		snap.Patients = map[string]*Patient{}
	}
	if snap.Encounters == nil {
		snap.Encounters = map[string]*Encounter{}
	}
	if snap.Records == nil {
		snap.Records = map[string]*Record{}
	}
	if snap.Versions == nil {
		snap.Versions = map[string]*Version{}
	}
	if snap.Authorizations == nil {
		snap.Authorizations = map[string]*Authorization{}
	}
	if snap.Exchanges == nil {
		snap.Exchanges = map[string]*Exchange{}
	}
}

// Close 刷新并释放数据目录。Close 后任何业务方法返回 ErrClosed。
func (s *Store) Close() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.lock == nil {
		return ErrClosed
	}
	unlockFile(s.lock)
	err := s.lock.Close()
	if rmErr := removeLockFile(filepath.Join(s.dir, ".clinical.lock")); rmErr != nil && !os.IsNotExist(rmErr) && err == nil {
		err = rmErr
	}
	s.lock = nil
	s.data = nil
	return err
}

func (s *Store) now() time.Time { return s.clock().UTC() }

// mutate 在状态的深拷贝上执行业务变更。fn 返回错误时，拷贝连同其中的
// 半成品一并丢弃，磁盘与既有业务状态保持原样；fn 返回 nil 时整体原子落盘。
// 这样“引用不存在的对象/跨患者混用”等失败都不会留下半条记录。
func (s *Store) mutate(fn func(*snapshot) error) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.data == nil {
		return ErrClosed
	}

	clone := cloneSnapshot(s.data)
	if err := fn(clone); err != nil {
		return err
	}
	if err := s.persist(clone); err != nil {
		return err
	}
	s.data = clone
	return nil
}

// view 在只读快照上执行查询。
func (s *Store) view(fn func(*snapshot) error) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.data == nil {
		return ErrClosed
	}
	return fn(s.data)
}

func (s *Store) persist(snap *snapshot) error {
	raw, err := json.MarshalIndent(snap, "", "  ")
	if err != nil {
		return err
	}
	final := filepath.Join(s.dir, dataName)
	tmp := filepath.Join(s.dir, dataName+".tmp")
	if err := os.WriteFile(tmp, raw, 0o600); err != nil {
		return err
	}
	if err := os.Rename(tmp, final); err != nil {
		_ = os.Remove(tmp)
		return err
	}
	return nil
}

func cloneSnapshot(in *snapshot) *snapshot {
	out := &snapshot{
		FormatVersion:  in.FormatVersion,
		Patients:       make(map[string]*Patient, len(in.Patients)),
		Encounters:     make(map[string]*Encounter, len(in.Encounters)),
		Records:        make(map[string]*Record, len(in.Records)),
		Versions:       make(map[string]*Version, len(in.Versions)),
		Authorizations: make(map[string]*Authorization, len(in.Authorizations)),
		Exchanges:      make(map[string]*Exchange, len(in.Exchanges)),
		AuditEvents:    make([]*AuditEvent, 0, len(in.AuditEvents)),
	}
	for k, v := range in.Patients {
		p := *v
		out.Patients[k] = &p
	}
	for k, v := range in.Encounters {
		e := *v
		out.Encounters[k] = &e
	}
	for k, v := range in.Records {
		r := *v
		r.Versions = append([]ID(nil), v.Versions...)
		out.Records[k] = &r
	}
	for k, v := range in.Versions {
		vv := *v
		out.Versions[k] = &vv
	}
	for k, v := range in.Authorizations {
		a := *v
		a.Scopes = append([]Scope(nil), v.Scopes...)
		a.Selections = append([]RecordSelection(nil), v.Selections...)
		if v.RevokedAt != nil {
			t := *v.RevokedAt
			a.RevokedAt = &t
		}
		out.Authorizations[k] = &a
	}
	for k, x := range in.Exchanges {
		y := *x
		y.Package.Records = append([]PackagedRecord(nil), x.Package.Records...)
		if x.Receipt != nil {
			r := *x.Receipt
			y.Receipt = &r
		}
		out.Exchanges[k] = &y
	}
	for _, ev := range in.AuditEvents {
		e := *ev
		out.AuditEvents = append(out.AuditEvents, &e)
	}
	return out
}

func newID(prefix string) string {
	var b [12]byte
	if _, err := rand.Read(b[:]); err != nil {
		// crypto/rand 失败在正常运行环境中不应发生；无法安全生成标识时直接中断。
		panic(fmt.Errorf("clinical: cannot generate id: %w", err))
	}
	return prefix + "_" + hex.EncodeToString(b[:])
}

func (s *Store) addAudit(snap *snapshot, patientID ID, actor Actor, action, objectType, objectID ID, at time.Time) {
	snap.AuditEvents = append(snap.AuditEvents, &AuditEvent{
		ID:         newID("aud"),
		PatientID:  patientID,
		ActorID:    actor.ID,
		Action:     action,
		ObjectType: objectType,
		ObjectID:   objectID,
		OccurredAt: at,
	})
}

package clinical

import (
	"errors"
	"time"
)

// 记录类别：诊断与医嘱。
const (
	Diagnosis = "diagnosis"
	Order     = "order"
)

// 审计动作。
const (
	ActionActivated   = "activated"
	ActionCorrected   = "corrected"
	ActionGranted     = "authorization_granted"
	ActionRevoked     = "authorization_revoked"
	ActionDeactivated = "patient_deactivated"
	ActionExchanged   = "exchange_created"
	ActionReceipted   = "receipt_registered"
)

// 合成数据标记。本包只处理合成患者资料，登记时统一写入。
const SyntheticSource = "synthetic"

// 调用方身份。Internal 为内部使用者，Receiver 为接收方。
//
// 内部使用者可查看全部草稿与完整历史、建立与撤回授权、维护档案；
// 接收方只能凭有效授权读取当前生效版本。
type Actor struct {
	ID   string
	Kind string // "internal" 或 "receiver"
}

// InternalActor 构造一个内部使用者身份。
func InternalActor(id string) Actor { return Actor{ID: id, Kind: "internal"} }

// ReceiverActor 构造一个接收方身份。
func ReceiverActor(id string) Actor { return Actor{ID: id, Kind: "receiver"} }

// IsInternal 报告该身份是否为内部使用者。
func (a Actor) IsInternal() bool { return a.Kind == "internal" }

func (a Actor) valid() bool {
	if a.ID == "" {
		return false
	}
	return a.Kind == "internal" || a.Kind == "receiver"
}

// ID 是患者、就诊、记录、版本、授权与审计事件的稳定标识。
// ID 在各自类型的集合内唯一，由登记操作生成并原样返回，
// 关闭后从同一位置重新打开仍然有效。
type ID = string

// Patient 是一名合成患者的档案。
type Patient struct {
	ID          ID
	Name        string
	Source      string // 始终为 SyntheticSource
	Deactivated bool
	CreatedAt   time.Time
}

// Encounter 是患者的一次就诊。
type Encounter struct {
	ID         ID
	PatientID  ID
	OccurredAt time.Time
	CreatedAt  time.Time
}

// Version 是一条记录在某一时刻被固化的完整内容。
// 生效产生第 1 版；每次更正产生新版本并通过 PrevID 链接到上一版本。
type Version struct {
	ID        ID
	RecordID  ID
	Number    int
	Content   string
	Category  string
	CreatedAt time.Time // 生效或更正发生的时间
	PrevID    ID        // 上一版本；第 1 版为空
	Reason    string    // 更正原因；第 1 版为空
}

// Record 是一条诊断或医嘱。它在草稿与版本之间推进：
// 草稿可反复修改或删除；生效后产生不可变的当前版本，
// 此后只能通过更正产生新版本，不能被直接覆盖或删除。
type Record struct {
	ID          ID
	PatientID   ID
	EncounterID ID
	Category    string

	DraftContent string
	HasDraft     bool

	CurrentVersionID ID
	Versions         []ID // 按版本号顺序，旧到新
}

// Authorization 是内部使用者为一名接收方建立的、针对某患者的读取授权。
// 范围由两类条目组成，二者可并存、均可覆盖多条就诊与类别：
//
//   - Scopes：整类范围，覆盖某次就诊下某个类别（诊断/医嘱）的全部已生效
//     记录，含授权建立之后才生效的记录；读取时始终取记录的当前生效版本。
//   - Selections：限定范围，仅覆盖明确选出的具体记录。被选记录被更正后
//     授权覆盖它的当前版本；但同一就诊同一类别的其他记录、以及后来新增
//     并生效的记录都不会自动进入限定范围。
//
// 授权仅在 [StartsAt, ExpiresAt) 内有效。
type Authorization struct {
	ID         ID
	PatientID  ID
	ReceiverID string
	Scopes     []Scope
	// Selections 为限定范围中明确选出的记录。为空表示该授权只有整类范围；
	// 旧数据与 Grant 建立的授权该字段始终为空。
	Selections []RecordSelection
	StartsAt   time.Time
	ExpiresAt  time.Time
	RevokedAt  *time.Time // 撤回时间；nil 表示未撤回
	CreatedAt  time.Time
}

// ActiveAt 报告授权在时刻 t 是否有效：已开始、未到期、未撤回。
// 开始时刻即生效；到截止时刻立即失效（半开区间 [StartsAt, ExpiresAt)）。
func (a *Authorization) ActiveAt(t time.Time) bool {
	if a.RevokedAt != nil {
		return false
	}
	if t.Before(a.StartsAt) {
		return false
	}
	if !t.Before(a.ExpiresAt) {
		return false
	}
	return true
}

// Scope 是授权范围中的一项：某次就诊下的某个记录类别。
type Scope struct {
	EncounterID ID
	Category    string
}

// RecordSelection 是授权限定范围中的一项：明确选出某条已生效记录，
// 并声明它所属的就诊与类别。建立授权时记录必须存在、已生效、属于该
// 患者，且其实际就诊与类别必须与声明一致；同一记录在一条授权内重复
// 选择只算一次。
type RecordSelection struct {
	EncounterID ID
	Category    string
	RecordID    ID
}

// AuditEvent 是一条仅供内部使用者按患者查看的审计事件。
type AuditEvent struct {
	ID         ID
	PatientID  ID
	ActorID    string
	Action     string
	ObjectType string
	ObjectID   ID
	OccurredAt time.Time
}

// ReadResult 是接收方一次受限读取得到的内容。
type ReadResult struct {
	EncounterID ID
	Category    string
	// Records 为该就诊该类别下、当前生效且被有效授权覆盖的记录，
	// 每项只含当前生效版本的完整内容，不含草稿、旧版本或更正原因。
	Records []EffectiveRecord
}

// EffectiveRecord 是对外暴露的一条当前生效记录。
type EffectiveRecord struct {
	RecordID    ID
	VersionID   ID
	Version     int
	Content     string
	EffectiveAt time.Time
}

// 交换状态：创建后待回执，接收方登记回执后转为已接受或已拒绝。
const (
	ExchangePending  = "pending_receipt"
	ExchangeAccepted = "accepted"
	ExchangeRejected = "rejected"
)

// 回执结果：接受或拒绝打包内容。
const (
	ReceiptAccepted = "accepted"
	ReceiptRejected = "rejected"
)

// PackagedRecord 是包内固化的一条记录版本。包在创建时取各记录的当前生效
// 版本快照：此后记录被更正或新增版本都不会改写包内容。
//
// 只含核对所需的标识、版本号、生效时间与完整内容，不含患者姓名、草稿、
// 历史版本或更正原因（Version.Reason）。
type PackagedRecord struct {
	EncounterID ID
	Category    string
	RecordID    ID
	VersionID   ID
	Version     int
	EffectiveAt time.Time
	Content     string
}

// Package 是一份已固化的交换内容：只含患者与接收方标识及各记录的版本快照。
type Package struct {
	PatientID  ID
	ReceiverID string
	Records    []PackagedRecord
}

// Receipt 是接收方对一份包的回执。接受时 Reason 为空；拒绝时 Reason 必填。
type Receipt struct {
	Outcome      string
	Reason       string
	RegisteredAt time.Time
}

// Exchange 是把已授权记录打包给指定接收方的一次交换。
//
// 创建即把当时的当前版本固化进 Package 并计算摘要；状态初始为待回执。
// 请求号（RequestID）按发起的内部使用者区分，用于安全重试：同一使用者以
// 相同请求号、患者、接收方、绑定授权与记录集合重试时返回原交换。
type Exchange struct {
	ID              ID
	PatientID       ID
	ReceiverID      string
	AuthorizationID ID
	RequestID       string
	CreatorID       string // 创建交换的内部使用者标识
	Status          string // ExchangePending/Accepted/Rejected
	Digest          string // 包内容摘要，接收方回执时须原样回传
	Package         Package
	Receipt         *Receipt
	CreatedAt       time.Time
}

// 失败一律返回明确错误，不留下半条记录。
var (
	// ErrNotFound 表示引用的患者、就诊、记录、版本或授权不存在。
	ErrNotFound = errors.New("clinical: referenced object not found")
	// ErrMismatchedPatient 表示混用了属于不同患者的对象。
	ErrMismatchedPatient = errors.New("clinical: objects belong to different patients")
	// ErrInvalidArgument 表示参数本身不合法（空内容、空范围、时间窗倒置等）。
	ErrInvalidArgument = errors.New("clinical: invalid argument")
	// ErrConflict 表示乐观并发冲突：指定的版本已不再是当前版本。
	ErrConflict = errors.New("clinical: version conflict")
	// ErrDeactivated 表示患者档案已停用，该写操作不再允许。
	ErrDeactivated = errors.New("clinical: patient record is deactivated")
	// ErrActive 表示记录已有生效版本，不能按草稿方式直接覆盖或删除。
	ErrActive = errors.New("clinical: record is already effective")
	// ErrAccessDenied 表示接收方没有覆盖所请求范围的有效授权，
	// 或内部规则不允许该身份执行此操作。返回时不携带任何受保护内容。
	ErrAccessDenied = errors.New("clinical: access denied")
	// ErrClosed 表示 Store 已关闭。
	ErrClosed = errors.New("clinical: store closed")
)

