220	// ---- 幂等重试：相同参数返回原交换，不重新取内容、不新增审计 ----
221	
222	func TestCreateExchangeIdempotentRetryAndFreeze(t *testing.T) {
223		f := setupExchange(t)
224	
225		x1, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.ord, f.diag}, "req-42")
226		if err != nil {
227			t.Fatal(err)
228		}
229	
230		// 打包后更正诊断到 v3；包应固定在 v2，Read 仍返回当前版本。
231		v3, err := f.s.CorrectRecord(doc, f.diag, 2, "诊断v3内容", "复核更新")
232		if err != nil {
233			t.Fatal(err)
234		}
235		res, err := f.s.Read(rcv, f.pid, f.e1, Diagnosis)
236		if err != nil {
237			t.Fatal(err)
238		}
239		if res.Records[0].Content != "诊断v3内容" || res.Records[0].VersionID != v3.ID {
240			t.Fatalf("Read must still return current version: %+v", res.Records)
241		}
242	
243		auditBefore := len(mustAudit(t, f.s, f.pid))
244	
245		// 顺序不同、重复标识、接收方以相同请求重试（仍由内部使用者发起）。
246		x2, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID,
247			[]ID{f.diag, f.ord, f.diag}, "req-42")
248		if err != nil {
249			t.Fatalf("retry: %v", err)
250		}
251		if x2.ID != x1.ID || x2.Digest != x1.Digest || !x2.CreatedAt.Equal(x1.CreatedAt) {
252			t.Fatalf("retry did not return original exchange:\n%+v\n%+v", x1, x2)
253		}
254		if len(x2.Package.Records) != 2 {
255			t.Fatalf("retry package records = %d, want 2", len(x2.Package.Records))
256		}
257		for _, pr := range x2.Package.Records {
258			if pr.RecordID == f.diag {
259				if pr.VersionID != f.diagV2.ID || pr.Content != "诊断v2内容" {
260					t.Fatalf("package refroze to new version: %+v", pr)
261				}
262			}
263		}
264		if got := len(mustAudit(t, f.s, f.pid)); got != auditBefore {
265			t.Fatalf("idempotent retry added audit events: %d -> %d", auditBefore, got)
266		}
267		if xs, _ := f.s.ListExchanges(doc, f.pid); len(xs) != 1 {
268			t.Fatalf("exchange count = %d, want 1", len(xs))
269		}
270	
271		// 其他参数变化 → ErrConflict。
272		otherRec, _ := f.s.CreateDraft(doc, f.pid, f.e2, Diagnosis, "二诊诊断")
273		if _, err := f.s.ActivateRecord(doc, otherRec.ID); err != nil {
274			t.Fatal(err)
275		}
276		authE2, _ := f.s.Grant(doc, f.pid, rcv.ID,
277			[]Scope{{EncounterID: f.e2, Category: Diagnosis}}, f.start, f.end)
278	
279		conflictCases := []struct {
280			name     string
281			pid      ID
282			receiver string
283			authID   ID
284			recs     []ID
285		}{
286			{"record set differs", f.pid, rcv.ID, f.auth.ID, []ID{f.diag, f.ord, otherRec.ID}},
287			{"record set subset", f.pid, rcv.ID, f.auth.ID, []ID{f.diag}},
288			{"receiver differs", f.pid, rcvB.ID, f.auth.ID, []ID{f.diag, f.ord}},
289			{"authorization differs", f.pid, rcv.ID, authE2.ID, []ID{f.diag, f.ord}},
290			{"patient differs", otherPID(t, f.s), rcv.ID, f.auth.ID, []ID{f.diag, f.ord}},
291		}
292		for _, c := range conflictCases {
293			if _, err := f.s.CreateExchange(doc, c.pid, c.receiver, c.authID, c.recs, "req-42"); !errors.Is(err, ErrConflict) {
294				t.Fatalf("%s: err = %v, want ErrConflict", c.name, err)
295			}
296		}
297	
298		// 另一内部使用者用相同请求号：互不干扰，各自一份。
299		xOther, err := f.s.CreateExchange(doc2, f.pid, rcv.ID, f.auth.ID, []ID{f.diag}, "req-42")
300		if err != nil {
301			t.Fatalf("other actor same request id: %v", err)
302		}
303		if xOther.ID == x1.ID {
304			t.Fatal("request id must be scoped per internal actor")
305		}
306	}
