335	// ---- 接收方取包：重新检查绑定授权与患者状态 ----
336	
337	func TestFetchPackageRechecksBinding(t *testing.T) {
338		f := setupExchange(t)
339		x, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.diag, f.ord}, "req-fetch")
340		if err != nil {
341			t.Fatal(err)
342		}
343	
344		del, err := f.s.FetchPackage(rcv, x.ID)
345		if err != nil {
346			t.Fatalf("fetch: %v", err)
347		}
348		if del.ExchangeID != x.ID || del.Digest != x.Digest || del.Status != ExchangePending {
349			t.Fatalf("bad delivery: %+v", del)
350		}
351		if len(del.Package.Records) != 2 || del.Package.PatientID != f.pid || del.Package.ReceiverID != rcv.ID {
352			t.Fatalf("bad package: %+v", del.Package)
353		}
354		if !del.CreatedAt.Equal(x.CreatedAt) {
355			t.Fatal("delivery created-at mismatch")
356		}
357	
358		// 其他接收方、内部使用者、不存在的交换统一拒绝。
359		if _, err := f.s.FetchPackage(rcvB, x.ID); !errors.Is(err, ErrAccessDenied) {
360			t.Fatalf("other receiver err = %v", err)
361		}
362		if _, err := f.s.FetchPackage(doc, x.ID); !errors.Is(err, ErrAccessDenied) {
363			t.Fatalf("internal actor err = %v", err)
364		}
365		if _, err := f.s.FetchPackage(rcv, "exch_missing"); !errors.Is(err, ErrAccessDenied) {
366			t.Fatalf("missing exchange err = %v", err)
367		}
368	
369		// 绑定授权到期：即便存在另一条覆盖同范围的有效授权也不能替代。
370		f.clk.t = f.end.Add(time.Minute)
371		otherAuth, err := f.s.Grant(doc, f.pid, rcv.ID,
372			[]Scope{{EncounterID: f.e1, Category: Diagnosis}, {EncounterID: f.e1, Category: Order}},
373			f.clk.t.Add(-time.Hour), f.clk.t.Add(24*time.Hour))
374		if err != nil {
375			t.Fatal(err)
376		}
377		_ = otherAuth
378		if del, err := f.s.FetchPackage(rcv, x.ID); !errors.Is(err, ErrAccessDenied) {
379			t.Fatalf("expired binding err = %v, delivery = %+v", err, del)
380		}
381	
382		// 回到窗口内：撤回绑定授权，另一条有效仍不能替代。
383		f.clk.t = f.start.Add(2 * time.Hour)
384		if err := f.s.Revoke(doc, f.pid, f.auth.ID); err != nil {
385			t.Fatal(err)
386		}
387		if _, err := f.s.FetchPackage(rcv, x.ID); !errors.Is(err, ErrAccessDenied) {
388			t.Fatalf("revoked binding err = %v", err)
389		}
390	
391		// 患者停用：拒绝。
392		if err := f.s.DeactivatePatient(doc, f.pid); err != nil {
