439		// 使用原摘要正常登记仍应成功——先前的本地修改没有让登记能力失效。
440		conf, err := f.s.SubmitReceipt(rcv, x.ID, originalDigest, ReceiptRejected, "接收方核对后真实拒绝")
441		if err != nil {
442			t.Fatalf("submit with original digest after local tamper: %v", err)
443		}
444		if conf.Status != ExchangeRejected || conf.Outcome != ReceiptRejected {
445			t.Fatalf("bad confirmation: %+v", conf)
446		}
