	// 再取一份。
	d2, err := f.s.FetchPackage(rcv, x.ID)
	if err != nil {
		t.Fatal(err)
	}

	// 改第一份包中的记录内容、标识、版本与集合：第二份保持取得时内容。
	tamperDeliveryResult(&d1)
	assertDeliveryMatches(t, d2, want, "second delivery after first tampered")

	// 再次取包仍是创建时固化的原内容与原摘要、原状态。
